/** Pure helpers: no I/O, no imports, no side effects. */

/** Split on whitespace and drop empty tokens. */
export function tokenize(text: string): string[] {
  return text.split(/\s+/).filter((token) => token.length > 0);
}

/** Lowercase, deduplicate and lexicographically sort words. */
export function normalize(text: string): string[] {
  const lowered = tokenize(text).map((token) => token.toLowerCase());
  return Array.from(new Set(lowered)).sort();
}

/** Join words into a comma-separated string. */
export function toCsv(words: string[]): string {
  return words.join(',');
}

